def dfs_recursive(graph, node, visited=None):
    if visited is None:
        visited = set()
    visited.add(node)
    print(f"Visited: {node}")
    for neighbor in graph.get(node, []):
        if neighbor not in visited:
            dfs_recursive(graph, neighbor, visited)
    return visited

graph = {'A': ['B', 'C'], 'B': ['D'], 'C': [], 'D': []}
dfs_recursive(graph, 'A')

def dfs_iterative(graph, start):
    visited = set()
    stack = [start]
    traversal = []
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            traversal.append(node)
            # Push neighbors (reversed to preserve left-to-right order)
            for neighbor in reversed(graph.get(node, [])):
                if neighbor not in visited:
                    stack.append(neighbor)
    return traversal

graph = {'A': ['B', 'C'], 'B': ['D', 'E'], 'C': [], 'D': [], 'E': []}
print(dfs_iterative(graph, 'A'))

class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val; self.left = left; self.right = right

def post_order_height(root: TreeNode) -> int:
    if not root: return 0
    left_h = post_order_height(root.left)
    right_h = post_order_height(root.right)
    # Post-order: compute current node using results of children
    return 1 + max(left_h, right_h)

root = TreeNode(1, TreeNode(2, TreeNode(4)), TreeNode(3))
print(f"Tree height: {post_order_height(root)}")

# 3-State Cycle Detection in Directed Graph
def has_cycle_directed(num_courses, prerequisites):
    graph = {i: [] for i in range(num_courses)}
    for dest, src in prerequisites:
        graph[src].append(dest)
    # 0 = unvisited, 1 = visiting (on stack), 2 = visited
    state = [0] * num_courses
    def dfs(node):
        if state[node] == 1: return True   # Cycle detected!
        if state[node] == 2: return False  # Already verified clean
        state[node] = 1  # Mark visiting
        for neighbor in graph[node]:
            if dfs(neighbor):
                return True
        state[node] = 2  # Mark visited
        return False
    return any(state[i] == 0 and dfs(i) for i in range(num_courses))

print(has_cycle_directed(2, [[1, 0], [0, 1]]))  # Cycle: 0 -> 1 -> 0
